type CatalogFxParams = dict[str, CatalogParamSpec]
"""
Parameter specs by name.
"""


class Clip(BaseModel):
    """
    A window onto an asset, placed in a lane (02 §3.6). The clip's end tick is derived from its warp.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    id: ClipId
    asset: Annotated[
        AssetHash, Field(description='Working asset (stem, generated audio, …).')
    ]
    srcStart: Annotated[int, Field(description='Samples into the asset.', ge=0)]
    srcEnd: Annotated[
        int,
        Field(
            description='Samples into the asset; srcStart < srcEnd (invariant 4.3.2).',
            ge=0,
        ),
    ]
    start: Annotated[int, Field(description='Ticks, relative to the section start.')]
    warp: Warp
    gainDb: float
    pitchSemitones: Annotated[
        float, Field(description='Pitch shift without tempo change.')
    ]
    fadeInTicks: Annotated[int, Field(ge=0)]
    fadeOutTicks: Annotated[int, Field(ge=0)]
    fadeCurve: FadeCurve
    reverse: bool | None = None
    fx: Annotated[
        FxChain | None,
        Field(description='Clip-level fx (rare, mostly paint-mode results).'),
    ] = None
    provenance: Provenance


class ClipAddOp(BaseModel):
    """
    `clip.add` (02 §4.2). Add a clip to a section's lane for a track.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    op: ClipAddOpOp
    sectionId: SectionId
    trackId: TrackId
    clip: Clip


class ClipPatch(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    srcStart: Annotated[int | None, Field(ge=0)] = None
    srcEnd: Annotated[int | None, Field(ge=0)] = None
    start: int | None = None
    warp: Warp | None = None
    gainDb: float | None = None
    pitchSemitones: float | None = None
    fadeInTicks: Annotated[int | None, Field(ge=0)] = None
    fadeOutTicks: Annotated[int | None, Field(ge=0)] = None
    fadeCurve: FadeCurve | None = None
    reverse: bool | None = None


class ClipReplaceOp(BaseModel):
    """
    `clip.replace` (02 §4.2). Replace one clip with N clips (AI results).
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    op: ClipReplaceOpOp
    clipId: ClipId
    clips: Annotated[list[Clip], Field(min_length=1)]


class ClipUpdateOp(BaseModel):
    """
    `clip.update` (02 §4.2). Patch a clip: move, trim, gain, fades, pitch, warp.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    op: ClipUpdateOpOp
    clipId: ClipId
    patch: ClipPatch


class FxAddOp(BaseModel):
    """
    `fx.add` (02 §4.2). Insert an effect into a track, clip or master chain.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    op: FxAddOpOp
    scope: FxScope
    fx: FxInstance
    index: Annotated[
        int | None,
        Field(description='Position in the chain; appended when absent.', ge=0),
    ] = None


class Highlight(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    region: Region
    label: Annotated[str, Field(min_length=1)]


type HighlightList = Annotated[list[Highlight], Field(title='HighlightList')]


class KeyTransposeOp(BaseModel):
    """
    `key.transpose` (02 §4.2). Set clip pitchSemitones in scope.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    op: KeyTransposeOpOp
    semitones: float
    scope: TransposeScope


class Lane(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    clips: list[Clip]
    automation: Annotated[
        AutomationList,
        Field(description='Lane automation is relative to the section start.'),
    ]


type LaneMap = Annotated[
    dict[TrackId, Lane],
    Field(description='Content per track, keyed by TrackId.', title='LaneMap'),
]


class Placement(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    region: Region
    trackId: TrackId | None = None
    newTrack: NewTrack | None = None
    mode: PlacementMode


class SectionInstance(BaseModel):
    """
    One section in the arrangement. Lane content is positioned RELATIVE to the section start (02 §3.5).
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    id: SectionId
    kind: SectionKind
    label: Annotated[
        str, Field(description='E.g. "Chorus 2" (auto-numbered unless user-renamed).')
    ]
    lengthTicks: Annotated[
        int, Field(description='Must be > 0, normally a whole number of bars.', gt=0)
    ]
    lanes: LaneMap
    transitionIn: Transition
    derivedFrom: Annotated[
        SectionId | None,
        Field(description='Set on duplicate, so the UI can show "copy of Chorus 1".'),
    ] = None
    energyTarget: EnergyTarget | None = None
    locked: Annotated[
        bool | None,
        Field(description='AI-authored batches may not modify locked sections.'),
    ] = None


class AnalysisApplyOp(BaseModel):
    """
    `analysis.apply` (02 §4.2). System op: record one analysis stage's result and reconcile the document with it (02 §6). The op is order-independent: the document depends on the set of recorded stages, not their arrival order.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    op: AnalysisApplyOpOp
    sourceId: SourceId
    stage: Annotated[
        AnalysisStage,
        Field(
            description='The stage that finished. Each stage owns at most one effect kind; stages that change no arrangement carry an empty `effects` list (02 §6).'
        ),
    ]
    blob: Annotated[AssetHash, Field(description="The stage's result blob.")]
    effects: Annotated[
        AnalysisEffectList,
        Field(
            description='The facts the document takes from the blob, in typed form. `bragi-model` cannot read blobs, so the producer projects them here (02 §6, Q12).'
        ),
    ]


class ApplyGeneratedStep(BaseModel):
    """
    Turns a generation job's output into clip ops (06 §3). Not offered in v1.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    kind: ApplyGeneratedStepKind
    from_: Annotated[str, Field(alias='from', min_length=1)]
    placement: Placement


class Arrangement(BaseModel):
    """
    Timebase, the ordered sections and the master bus (02 §3.5). Absolute section positions are derived, never stored.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    timebase: Timebase
    sections: Annotated[
        list[SectionInstance],
        Field(
            description='ORDERED. The absolute start tick of section i is the sum of lengthTicks of sections[0..i).'
        ),
    ]
    master: Master


class CatalogFxDefinition(BaseModel):
    """
    One effect's parameters.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    system: Annotated[
        bool | None,
        Field(description='Generated by the system, not offered in the expert drawer.'),
    ] = None
    masterOnly: Annotated[
        bool | None, Field(description='Allowed only on the master chain.')
    ] = None
    params: CatalogFxParams


type CatalogFxMap = dict[str, CatalogFxDefinition]
"""
Every effect by FxType.
"""


class Explanation(BaseModel):
    """
    The answer to "Explain this" (06 §8). Every claim is grounded in an analysis feature; the highlights are drawn on the canvas.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    text: Annotated[str, Field(max_length=4000, min_length=1)]
    highlights: HighlightList
    learnMore: Annotated[str | None, Field(min_length=1)] = None


class FxCatalog(BaseModel):
    """
    The DSP catalogue (03 §6): one source shared by the UI (control ranges), the planner (allowed params) and bragi-model::validate. The instance is crates/bragi-dsp/fx_catalog.json.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    field_comment: Annotated[
        str | None,
        Field(
            alias='$comment',
            description='Free-form provenance note carried by the source file.',
        ),
    ] = None
    version: Annotated[int, Field(ge=1)]
    fx: CatalogFxMap


class Project(BaseModel):
    """
    A song document: the single source of truth for a project (specs/02-song-model.md §2, §3.1). Changed only through bragi-model ops.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    schemaVersion: ProjectSchemaVersion
    id: ProjectId
    meta: ProjectMeta
    sources: list[Source]
    analyses: AnalysisRefMap
    tracks: list[Track]
    arrangement: Arrangement


class SectionInsertOp(BaseModel):
    """
    `section.insert` (02 §4.2). Insert a section at index.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    op: SectionInsertOpOp
    index: Annotated[int, Field(description='Position in arrangement.sections.', ge=0)]
    section: SectionInstance


type Op = Annotated[
    ProjectSetMetaOp | AnalysisApplyOp | TrackAddOp | TrackRemoveOp | TrackUpdateOp | FxAddOp | FxRemoveOp | FxReorderOp | FxUpdateOp | SectionDuplicateOp | SectionInsertOp | SectionMergeOp | SectionMoveOp | SectionRemoveOp | SectionResizeOp | SectionSetTransitionOp | SectionSplitOp | SectionUpdateOp | ClipAddOp | ClipRemoveOp | ClipReplaceOp | ClipSplitOp | ClipUpdateOp | AutomationClearOp | AutomationSetOp | TempoSetOp | KeyTransposeOp | RegionAdoptOp | RegionClearOp,
    Field(
        description='One concrete edit operation (02 §4). Every op is an object whose `op` field names it; the rest is its payload (02 §4.2).',
        title='Op',
    ),
]


class OpBatch(BaseModel):
    """
    An atomic group of ops: it applies fully or not at all (02 §4.1).
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    id: BatchId
    author: BatchAuthor
    intent: Annotated[
        str | None,
        Field(description='The user\'s words, e.g. "make the drums half-time".'),
    ] = None
    label: Annotated[
        str,
        Field(
            description='Short human label for history: "Half-time drums (verse 2)".'
        ),
    ]
    ops: Annotated[list[Op], Field(min_length=1)]
    createdAt: IsoDate


type OpList = Annotated[list[Op], Field(min_length=1, title='OpList')]


class OpsStep(BaseModel):
    """
    Ops applied directly and instantly (06 §3).
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    kind: OpsStepKind
    ops: OpList


class PlanRequest(BaseModel):
    """
    One planner request (06 §2). v1 carries the song document because the server holds no projects (docs/wp/2.6.md); the API never stores it.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    doc: Annotated[
        Project,
        Field(
            description='The `Project` at the commit the user is looking at. Analyses travel inside it.'
        ),
    ]
    prompt: Annotated[
        str,
        Field(
            description="The user's words. Untrusted: escaped and placed in a data block before it reaches the model.",
            max_length=2000,
            min_length=1,
        ),
    ]
    region: Annotated[
        Region | None,
        Field(
            description='The lasso / selection the prompt targets. Absent for song chat.'
        ),
    ] = None
    uiContext: PlannerUiContext
    variantCount: PlanVariantCount | None = None
    preferences: PlanPreferences | None = None
    explain: Annotated[
        bool | None,
        Field(description='Ask for an `Explanation` instead of an `EditPlan` (06 §8).'),
    ] = None
    libraryNames: Annotated[
        LibraryNameList | None,
        Field(
            description="Artist and title strings from the user's library, for the content-policy pre-pass (10 §7)."
        ),
    ] = None


type PlanStep = Annotated[
    OpsStep | GenerateStep | ApplyGeneratedStep | SmoothStep, Field(title='PlanStep')
]


type PlanStepList = Annotated[list[PlanStep], Field(min_length=1, title='PlanStepList')]


class PlanVariant(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    label: Annotated[str, Field(min_length=1)]
    description: Annotated[str, Field(min_length=1)]
    steps: PlanStepList
    scope: Annotated[
        PlanVariantScope | None,
        Field(
            description='Set to `song` when the variant intentionally changes the whole song; only valid with a song-wide prompt (06 §7).'
        ),
    ] = None


type PlanVariantList = Annotated[
    list[PlanVariant], Field(max_length=3, title='PlanVariantList')
]


class Commit(BaseModel):
    """
    A node in the version DAG: one op batch plus a full snapshot of the document after it (02 §7).
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    id: CommitId
    projectId: ProjectId
    parents: Annotated[
        list[CommitId],
        Field(
            description='Empty for the root commit, one parent otherwise. Never two in v1: there are no true merges (region.adopt instead).',
            max_length=1,
        ),
    ]
    batch: OpBatch
    snapshot: Annotated[
        AssetHash,
        Field(
            description='Uncompressed canonical JSON of the full document after this commit, content-addressed in the BlobCache (02 §7). zstd is a later optimisation (Q85).'
        ),
    ]
    state: CommitState
    candidateGroup: Annotated[
        str | None,
        Field(description='Candidates produced by one AI request share a group.'),
    ] = None
    deviceId: Annotated[str, Field(min_length=1)]
    createdAt: IsoDate


class EditPlan(BaseModel):
    """
    A plan the planner offers as 1–3 variants (06 §3). v1 only executes `ops` steps; the other kinds are part of the contract for WP-2.7.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    planId: PlanId
    interpretation: Annotated[
        str,
        Field(
            description='Plain language: what the planner understood and will do.',
            max_length=2000,
            min_length=1,
        ),
    ]
    clarification: Annotated[
        Clarification | None,
        Field(
            description='Only when the request is truly ambiguous; then `variants` may be empty.'
        ),
    ] = None
    variants: PlanVariantList
    estimatedCredits: Annotated[float, Field(ge=0.0)]
    estimatedSeconds: Annotated[float, Field(ge=0.0)]
    notices: Annotated[
        NoticeList | None,
        Field(
            description='Plain-language notes about transformations the planner made, e.g. an artist name rewritten as descriptors (10 §7).'
        ),
    ] = None


